CREATE TABLE IF NOT EXISTS bases(id SERIAL PRIMARY KEY,name TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS equipment(id SERIAL PRIMARY KEY,name TEXT UNIQUE NOT NULL,category TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('admin','commander','logistics')),base_id INTEGER REFERENCES bases(id));
CREATE TABLE IF NOT EXISTS stock(base_id INTEGER REFERENCES bases(id),equipment_id INTEGER REFERENCES equipment(id),quantity INTEGER NOT NULL DEFAULT 0 CHECK(quantity>=0),PRIMARY KEY(base_id,equipment_id));
CREATE TABLE IF NOT EXISTS transactions(id BIGSERIAL PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN ('purchase','transfer','expenditure')),equipment_id INTEGER NOT NULL REFERENCES equipment(id),source_base_id INTEGER REFERENCES bases(id),destination_base_id INTEGER REFERENCES bases(id),quantity INTEGER NOT NULL CHECK(quantity>0),note TEXT DEFAULT '',created_by INTEGER REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS assignments(id BIGSERIAL PRIMARY KEY,base_id INTEGER NOT NULL REFERENCES bases(id),equipment_id INTEGER NOT NULL REFERENCES equipment(id),personnel TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','returned')),assigned_at TIMESTAMPTZ DEFAULT NOW(),returned_at TIMESTAMPTZ,created_by INTEGER REFERENCES users(id));
CREATE TABLE IF NOT EXISTS audit_logs(id BIGSERIAL PRIMARY KEY,user_id INTEGER REFERENCES users(id),method TEXT NOT NULL,path TEXT NOT NULL,status INTEGER NOT NULL,details JSONB,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_tx_time ON transactions(created_at);CREATE INDEX IF NOT EXISTS idx_tx_equipment ON transactions(equipment_id);CREATE INDEX IF NOT EXISTS idx_audit_time ON audit_logs(created_at);
